            "Se le acabará todo todo el calor y será triste e invisiblemente invisiblemente invisiblemente una roca carbón bola bola enana enana totalmente oscurísima invisible fría negra fría y silenciosa muerta solitaria llamada muerta invisiblemente grandísima enana oscura invisible fría y negra Enana Negra",
